func:
// TASK SETTINGS of the PBI report build: folders, sites, dry run, calendar.
// In: msg.payload = the job {tables: [...], sites: [...]}. Both are optional,
// no list means all. Out: the same message with msg.job, the settings stored.
// Folders in the data lake, without a leading slash.
var IN_REFERENCE = 'eu_report/reference';
var OUT_ROOT = 'eu_report/pbi_report/report';
// Sites that have files in the data lake.
var ALL_SITES = [
  'Hull',
  'Nottingham',
  'Weinheim'
];
var DRY_RUN = {
  pbi_machine_names: true,
  pbi_shift_naming: true,
  pbi_calendar: true
};
// First and last date of the calendar table (the report uses 2011 to 2050).
var CALENDAR_START = '2011-01-01';
var CALENDAR_END = '2050-12-31';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}

var asked = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
var allTables = Object.keys(DRY_RUN);
var tables = Array.isArray(asked.tables) ? asked.tables : allTables;
var sites = Array.isArray(asked.sites) ? asked.sites : ALL_SITES;
var unknown = tables.filter(function (t) {
  return allTables.indexOf(t) === -1;
}).concat(sites.filter(function (s) {
  return ALL_SITES.indexOf(s) === -1;
}));
if (unknown.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'unknown: ' + unknown.join(', ')
  });
  node.error('unknown table or site in the job: ' + unknown.join(', '));
  return null;
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.referenceFolder = IN_REFERENCE;
cfg.calendarStart = CALENDAR_START;
cfg.calendarEnd = CALENDAR_END;
cfg.paths = {};
allTables.forEach(function (table) {
  cfg.paths[table] = OUT_ROOT + '/' + table + '/' + table + '.parquet';
});
flow.set('cfg', cfg);

msg.job = {
  tables: tables,
  sites: sites
};
var writing = tables.filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts the jobs of the run. In: msg.job {tables, sites} from the settings.
// Out 1: machine names, payload = the site list (a split follows). Out 2: shift
// names. Out 3: calendar. A table that is not in the job gets no message.
var job = msg.job;
var day = new Date().toISOString().slice(0, 10);
var loadedAt = Date.now();

function start(table, payload) {
  if (job.tables.indexOf(table) === -1) {
    return null;
  }
  return {
    payload: payload,
    job: job,
    table: table,
    day: day,
    mode: 'report',
    loadedAt: loadedAt
  };
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: job.tables.length + ' table(s), ' + job.sites.length + ' site(s)'
});
return [
  start('pbi_machine_names', job.sites),
  start('pbi_shift_naming', []),
  start('pbi_calendar', [])
];

// Sets the folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the machine rows of one site from its Machine Names file.
// In: msg.payload = the parsed rows (MachineName, Dept, Area, Product Type).
// Out: msg.payload = an item {name, failed, skipped, rows} for the join.
// The rules are those of the load queries of the report (Machine Names H, N).
var RULES = {
  Hull: {
    dropNames: [
      'GT4 - Auto'
    ],
    keepDepts: [
      'Dries Pack',
      'Liquids Pack'
    ]
  },
  Nottingham: {
    keepAreas: [
      'SD Packing',
      'Strepsils Packing'
    ]
  },
  Weinheim: {},
  Mira: {}
};

var site = msg.site;
var rule = RULES[site] || {};
var item = {
  name: site,
  failed: null,
  skipped: null,
  rows: []
};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  item.failed = 'machine names ' + site + ': no MachineName column or rows';
  msg.payload = item;
  return msg;
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function allowed(list, value) {
  return !list || list.indexOf(value) !== -1;
}

var dropped = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  var dept = text(row.Dept);
  var area = text(row.Area);
  var drop = !name ||
    (rule.dropNames && rule.dropNames.indexOf(name) !== -1) ||
    !allowed(rule.keepDepts, dept) ||
    !allowed(rule.keepAreas, area);
  if (drop) {
    dropped++;
    return;
  }
  item.rows.push({
    site_name: site,
    area: area,
    dept: dept,
    machine_name: name,
    product_type: text(row['Product Type']),
    unique_machine_name: name + '-' + site,
    loaded_at: msg.loadedAt
  });
});
if (dropped) {
  item.skipped = site + ': ' + dropped + ' row(s) left out by the report rules';
}
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table pbi_machine_names.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_machine_names';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_machine_names'];
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the folder of the shift patterns file for the list objects node.
// In: the shift names job. Out: msg.site, msg.what and msg.path = the folder.
// The file has no site column, so it lives in the folder site=All.
var TYPE_FOLDER = 'shift_naming';
var SITE = 'All';
var cfg = flow.get('cfg');

msg.site = SITE;
msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + SITE + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the shift rows from the Shift Patterns file.
// In: msg.payload = the parsed rows (ShiftName, Shift).
// Out: msg.payload = an item {name, failed, skipped, rows}: one row per line
// of the file; the distinct step after the collect keeps each shift once.
var item = {
  name: 'shift patterns',
  failed: null,
  skipped: null,
  rows: []
};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].Shift === undefined) {
  item.failed = 'shift patterns: no Shift column or rows';
  msg.payload = item;
  return msg;
}

rows.forEach(function (row) {
  var shift = String(row.Shift === undefined ? '' : row.Shift).trim();
  if (shift) {
    item.rows.push({
      shift: shift,
      loaded_at: msg.loadedAt
    });
  }
});
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Keeps every shift name once.
// In: msg.rows = the shift rows of all calendars (names repeat).
// Out: msg.rows = the distinct shift names, in the order first seen.
var seen = {};
msg.rows = msg.rows.filter(function (row) {
  if (seen[row.shift]) {
    return false;
  }
  seen[row.shift] = true;
  return true;
});
return msg;

// Decides what happens with the table pbi_shift_naming.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_shift_naming';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_shift_naming'];
msg.filename = msg.path.split('/').pop();
return msg;

// Builds the pbi_calendar table: one row per date, Monday week start.
// In: any message after the settings node. Out 1: msg.payload = the rows
// (topic pbi_calendar). Out 2: a log line. Dry run sends only the log line.
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
var MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December'
];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}

// ISO week number (Monday start, week 1 holds the first Thursday).
function isoWeek(ms) {
  var d = new Date(ms);
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  var yearStart = Date.UTC(d.getUTCFullYear(), 0, 1);
  return Math.ceil(((d.getTime() - yearStart) / DAY_MS + 1) / 7);
}

var rows = [];
var start = Date.parse(cfg.calendarStart + 'T00:00:00Z');
var end = Date.parse(cfg.calendarEnd + 'T00:00:00Z');
for (var t = start; t <= end; t += DAY_MS) {
  var d = new Date(t);
  var month = d.getUTCMonth();
  var year = d.getUTCFullYear();
  var quarter = Math.floor(month / 3) + 1;
  var mondayOffset = (d.getUTCDay() + 6) % 7;
  rows.push({
    date: d.toISOString().slice(0, 10),
    year: year,
    month_number: month + 1,
    month: MONTHS[month],
    month_short_name: MONTHS[month].slice(0, 3),
    month_year: MONTHS[month].slice(0, 3) + ' ' + year,
    month_year_number: pad(month + 1) + ' ' + String(year).slice(2),
    quarter: 'QTR' + quarter,
    quarter_number: quarter,
    week_number: isoWeek(t),
    week_start: new Date(t - mondayOffset * DAY_MS).toISOString().slice(0, 10)
  });
}

var text = 'pbi_calendar ' + rows.length + ' rows';
if (cfg.dryRun.pbi_calendar) {
  var line = {
    topic: 'log',
    payload: 'calendar [setup] DRY RUN: ' + text
  };
  return [null, line];
}
var table = {
  topic: 'pbi_calendar',
  day: '',
  payload: rows
};
return [table, null];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_calendar'];
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'pbi-report';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'pbi-report';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
